function validate([workers, bikes]) {
  if (!Array.isArray(workers) || !Array.isArray(bikes)) return 'workers and bikes are lists of [x, y] points.';
  if (workers.length < 1 || bikes.length > 10 || workers.length > bikes.length) return 'Need 1 <= workers.length <= bikes.length <= 10.';
  const seen = new Set();
  for (const p of [...workers, ...bikes]) {
    if (!Array.isArray(p) || p.length !== 2 || !p.every(v => Number.isInteger(v) && v >= 0 && v < 1000)) return 'Each position is [x, y] with integers from 0 to 999.';
    const key = p[0] * 1000 + p[1];
    if (seen.has(key)) return 'All worker and bike positions must be different.';
    seen.add(key);
  }
  return null;
}

