function assignBikes(workers, bikes) {
  const n = workers.length;
  const m = bikes.length;
  const full = 1 << m;
  const dp = new Array(full).fill(Infinity);
  const used = new Array(full).fill(0);
  dp[0] = 0;
  let best = Infinity;

  for (let mask = 0; mask < full; mask++) {
    used[mask] = used[mask >> 1] + (mask & 1);
    if (dp[mask] === Infinity) continue;
    const worker = used[mask];
    if (worker === n) {
      best = Math.min(best, dp[mask]);
      continue;
    }
    const [wx, wy] = workers[worker];
    for (let bike = 0; bike < m; bike++) {
      if (mask & (1 << bike)) continue;
      const [bx, by] = bikes[bike];
      const next = mask | (1 << bike);
      const cost = dp[mask] + Math.abs(wx - bx) + Math.abs(wy - by);
      dp[next] = Math.min(dp[next], cost);
    }
  }
  return best;
}

