function assignBikes(workers, bikes) {
  const taken = new Array(bikes.length).fill(false);
  let best = Infinity;
  const search = (i, total) => {
    if (total >= best) return;
    if (i === workers.length) { best = total; return; }
    for (let j = 0; j < bikes.length; j++) {
      if (taken[j]) continue;
      taken[j] = true;
      search(i + 1, total + Math.abs(workers[i][0] - bikes[j][0]) + Math.abs(workers[i][1] - bikes[j][1]));
      taken[j] = false;
    }
  };
  search(0, 0);
  return best;
}

