function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const m = size === 'small' ? int(1, 6) : 10;
  const n = size === 'small' ? int(1, m) : int(7, m);
  // The grid must hold n + m distinct points.
  const span = Math.max(Math.ceil(Math.sqrt(n + m)) + 1, size === 'small' ? [3, 6, 10][int(0, 2)] : [20, 1000][int(0, 1)]);
  const seen = new Set();
  const point = () => {
    for (;;) {
      const p = [int(0, span - 1), int(0, span - 1)];
      const key = p[0] * 1000 + p[1];
      if (!seen.has(key)) { seen.add(key); return p; }
    }
  };
  const workers = Array.from({ length: n }, point);
  const bikes = Array.from({ length: m }, point);
  return [workers, bikes];
}
